@@ -3723,19 +3736,6 @@ cs_mesh_quantities_solid_compute(const cs_mesh_t       *m,
       if (f_vtx_coord != (cs_real_3_t *)_f_vtx_coord)
         BFT_FREE(f_vtx_coord);

-      /* Adjusting face porosity and COG
