    if (c_id > -1) {
      cs_real_t pyra_vol_3
        = cs_math_3_distance_dot_product(a_cell_cen[c_id],
                                         b_f_face_cog[f_id],
                                         b_f_face_normal[f_id]);

      for (cs_lnum_t i = 0; i < 3; i++)
        _cell_f_cen[c_id][i] += pyra_vol_3 *(  0.75*b_f_face_cog[f_id][i]
