  const  cs_lnum_t  n_cells = m->n_cells;
  const  cs_lnum_t  n_cells_ext = m->n_cells_with_ghosts;
  const  cs_lnum_2_t  *i_face_cells
    = (const cs_lnum_2_t *)(m->i_face_cells);
  const  cs_lnum_t  *b_face_cells = m->b_face_cells;

