  const  cs_lnum_t  n_i_faces = m->n_i_faces;
  const  cs_lnum_t  n_b_faces = m->n_b_faces;
  const  cs_lnum_t  n_cells = m->n_cells;
  const  cs_lnum_t  n_cells_ext = m->n_cells_with_ghosts;
